mapper.select:
select c.*
from lab_consumable c
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}


    and c.consumable_name like concat('%', #{consumableName}, '%')


    and c.consumable_code like concat('%', #{consumableCode}, '%')


    and l.department_id = #{departmentId}


    and c.status = #{status}

order by c.id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_consumable c
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0

    and c.lab_id = #{labId}


    and l.lab_type = #{labType}


    and c.consumable_name like concat('%', #{consumableName}, '%')


    and c.consumable_code like concat('%', #{consumableCode}, '%')


    and l.department_id = #{departmentId}


    and c.status = #{status}

select c.* from lab_consumable c join lab l on l.id = c.lab_id where c.deleted = 0 and l.deleted = 0 and c.stock_quantity <= c.warning_threshold
and l.department_id = #{departmentId}
order by c.id desc

mapper.update:
update lab_consumable
set stock_quantity = #{stockQuantity}
where id = #{id}
    and deleted = 0

update lab_consumable
set stock_quantity = stock_quantity - #{quantity}
where id = #{id}
    and deleted = 0
    and stock_quantity >= #{quantity}

mapper.sql:
from lab_consumable c
join lab l on l.id = c.lab_id
where c.deleted = 0
  and l.deleted = 0
  and l.department_id = #{departmentId}

    and l.lab_type = #{labType}


    and c.lab_id = #{labId}

mapper.select:
select c.consumable_name as consumableName, l.lab_name as labName, coalesce(nullif(l.lab_type, ''), '未分类') as labType, c.stock_quantity as stockQuantity, c.warning_threshold as warningThreshold, c.unit as unit, coalesce(sum(case when log.change_type = 'IN' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day) then abs(log.change_amount) else 0 end), 0) as inQuantity, coalesce(sum(case when log.change_type = 'OUT' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day) then abs(log.change_amount) else 0 end), 0) as outQuantity, max(case when log.change_type = 'IN' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day) then log.created_at end) as lastInTime, max(case when log.change_type = 'OUT' and log.created_at >= #{startDate} and log.created_at < date_add(#{endDate}, interval 1 day) then log.created_at end) as lastOutTime, case when c.stock_quantity <= c.warning_threshold then 1 else 0 end as lowStock from lab_consumable c join lab l on l.id = c.lab_id left join consumable_stock_log log on log.consumable_id = c.id where c.deleted = 0 and l.deleted = 0 and l.department_id = #{departmentId}
and l.lab_type = #{labType}
and c.lab_id = #{labId}
group by c.id, c.consumable_name, l.lab_name, l.lab_type, c.stock_quantity, c.warning_threshold, c.unit order by c.id desc limit #{limit}
